<?php
require_once __DIR__.'/config/auth.php';$user=require_admin();$id=(int)($_GET['id']??$_POST['id']??0);$pdo=db();$s=$pdo->prepare('SELECT * FROM archives WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a)exit('Archive not found.');$s=$pdo->prepare('SELECT * FROM archive_documents WHERE archive_id=? ORDER BY slot_no LIMIT 1');$s->execute([$id]);$doc=$s->fetch();$s=$pdo->prepare('SELECT * FROM payments WHERE archive_id=? LIMIT 1');$s->execute([$id]);$pay=$s->fetch();$errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$moved=[];$oldFiles=[];try{$ref=trim((string)($_POST['ref_number']??''));$name=trim((string)($_POST['sender_name']??''));$phone=trim((string)($_POST['sender_phone']??''));$amount=filter_var($_POST['amount']??null,FILTER_VALIDATE_FLOAT);if($ref==='')$errors[]='Reference number is required.';$s=$pdo->prepare('SELECT id FROM archives WHERE ref_number=? AND id<>?');$s->execute([$ref,$id]);if($s->fetch())$errors[]='That reference number is already in use.';$newDoc=$doc;if(isset($_FILES['document_1'])&&($_FILES['document_1']['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){$path=upload_file($_FILES['document_1'],'documents');$moved[]=$path;if($doc)$oldFiles[]=$doc['file_path'];$newDoc=['slot_no'=>1,'file_path'=>$path,'original_name'=>substr((string)$_FILES['document_1']['name'],0,255)];}if(isset($_POST['remove_document'])&&!$newDoc)$errors[]='One document is required.';if($name===''||$phone===''||$amount===false||$amount<=0)$errors[]='Sender name, phone, and an amount greater than zero are required.';if(!$errors){$pdo->beginTransaction();$pdo->prepare('UPDATE archives SET ref_number=?,updated_by=? WHERE id=?')->execute([$ref,$user['id'],$id]);$pdo->prepare('DELETE FROM archive_documents WHERE archive_id=?')->execute([$id]);$ins=$pdo->prepare('INSERT INTO archive_documents(archive_id,slot_no,original_name,file_path) VALUES(?,?,?,?)');$ins->execute([$id,1,$newDoc['original_name'],$newDoc['file_path']]);if($pay)$pdo->prepare('UPDATE payments SET sender_name=?,sender_phone=?,amount=? WHERE archive_id=?')->execute([$name,$phone,$amount,$id]);else$pdo->prepare('INSERT INTO payments(archive_id,sender_name,sender_phone,amount,received_by) VALUES(?,?,?,?,?)')->execute([$id,$name,$phone,$amount,$user['id']]);$pdo->commit();foreach(array_unique($oldFiles) as $f)remove_file($f);log_activity('archive updated','archive',$id,$ref,'Archive document and payment updated',$user);flash('success','Archive updated successfully.');redirect('archive_view.php?id='.$id);}foreach($moved as $f)remove_file($f);$doc=$newDoc;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();foreach($moved as $f)remove_file($f);$errors[]='The archive could not be updated.';}}
$title='Edit Archive';require __DIR__.'/includes/header.php';?><div class="page-head"><div><h1>Edit archive</h1><p class="muted">Update the reference, document, and payment together.</p></div></div><?php foreach($errors as $err):?><div class="alert error"><?=e($err)?></div><?php endforeach;?><div class="card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$id?>"><div class="field"><label for="ref_number">Reference No</label><input id="ref_number" name="ref_number" required value="<?=e($_POST['ref_number']??$a['ref_number'])?>"></div><h2>Document</h2><div class="upload-tile"><div class="field"><label for="document_1">Replace document</label><?php if($doc):?><small class="muted">Current: <?=e($doc['original_name'])?></small><?php endif;?><input id="document_1" type="file" name="document_1" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png"><small class="muted">PDF, JPG, JPEG, PNG · maximum 500 MB · no minimum size</small></div></div><h2>Payment</h2><div class="grid grid-2"><div class="field"><label>Sender name</label><input name="sender_name" required value="<?=e($_POST['sender_name']??$pay['sender_name']??'')?>"></div><div class="field"><label>Sender phone</label><input name="sender_phone" inputmode="tel" required value="<?=e($_POST['sender_phone']??$pay['sender_phone']??'')?>"></div><div class="field"><label>Amount</label><input type="number" name="amount" inputmode="decimal" min="0.01" step="0.01" required value="<?=e($_POST['amount']??$pay['amount']??'')?>"></div></div><div class="actions"><button class="btn success">Save changes</button><a class="btn light" href="archive_view.php?id=<?=$id?>">Cancel</a></div></form></div><?php require __DIR__.'/includes/footer.php';
